# Test the formula
# Input: [8, 8, 8, 8, 8, 1], k = 5 (run length of 8s at start)
# Output height = 11, width = 6

input_vals = [8, 8, 8, 8, 8, 1]
width = len(input_vals)  # 6
height = 11
k = sum(1 for x in input_vals[:min(5, len(input_vals))] if input_vals[0] == x)  # k = 5

# But actually, k should be the run length of input[0] at start. For input = [8,8,8,8,8,1], k = 5.
# For a general input, we count how many times input[0] repeats at start.

def count_initial_run(arr):
    if not arr:
        return 0
    count = 0
    for x in arr:
        if x == arr[0]:
            count += 1
        else:
            break
    return count

k = count_initial_run(input_vals)
print(f"k = {k}")

output = []
for i in range(height):
    for j in range(width):
        if j < k + i:
            output[i][j] = input_vals[0]
        else:
            output[i][j] = input_vals[j - i]
    output.append(output[i])

print("\nOutput grid:")
for row in output:
    print(row)
print(f"\nSize: {len(output)} x {len(output[0])}")

